;(() => {
  const store = {
    get(key) {
      try {
        return localStorage.getItem(key)
      } catch {
        return null
      }
    },
    set(key, value) {
      try {
        localStorage.setItem(key, value)
      } catch {}
    },
  }
  const root = document.documentElement
  const THEME_KEY = 'mod-scanner.theme'
  const LANG_KEY = 'mod-scanner.lang'

  const savedTheme = store.get(THEME_KEY)
  if (savedTheme === 'light' || savedTheme === 'dark') root.dataset.theme = savedTheme

  let lang = store.get(LANG_KEY)
  if (lang !== 'vi' && lang !== 'en') lang = /^vi\b/i.test(navigator.language || '') ? 'vi' : 'en'

  const listeners = []
  const isDark = () =>
    root.dataset.theme ? root.dataset.theme === 'dark' : window.matchMedia('(prefers-color-scheme: dark)').matches

  function labelTheme() {
    const dark = isDark()
    const label = lang === 'vi' ? (dark ? 'Chuyển sang giao diện sáng' : 'Chuyển sang giao diện tối') : dark ? 'Switch to light mode' : 'Switch to dark mode'
    for (const button of document.querySelectorAll('[data-theme-toggle]')) {
      button.setAttribute('aria-label', label)
      button.title = label
    }
  }

  function applyLanguage() {
    root.lang = lang
    for (const el of document.querySelectorAll('[data-i18n]')) {
      if (el.dataset.en === undefined) el.dataset.en = el.innerHTML
      const vi = VI[el.dataset.i18n]
      el.innerHTML = lang === 'vi' && vi ? vi : el.dataset.en
    }
    for (const button of document.querySelectorAll('[data-lang]')) {
      button.setAttribute('aria-pressed', String(button.dataset.lang === lang))
    }
    labelTheme()
    for (const fn of listeners) fn(lang)
  }

  window.modScanner = {
    get lang() {
      return lang
    },
    onLanguage(fn) {
      listeners.push(fn)
    },
  }

  document.addEventListener('DOMContentLoaded', () => {
    for (const button of document.querySelectorAll('[data-lang]')) {
      button.addEventListener('click', () => {
        lang = button.dataset.lang
        store.set(LANG_KEY, lang)
        applyLanguage()
      })
    }
    for (const button of document.querySelectorAll('[data-theme-toggle]')) {
      button.addEventListener('click', () => {
        const next = isDark() ? 'light' : 'dark'
        root.dataset.theme = next
        store.set(THEME_KEY, next)
        labelTheme()
      })
    }
    window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', labelTheme)
    applyLanguage()
  })
})()
